        raise ValueError('n tidak boleh negatif')
    if n <= 1:
        return 1
    return n * faktorial_rekursif(n - 1)

def simpan_dan_filter_file(nama_file, baris_list, awalan=''):
    with open(nama_file, 'w', encoding='utf-8') as f:
        for baris in baris_list:
            f.write(f'{baris}\n')
    with open(nama_file, 'r', encoding='utf-8') as f:
        return [line for line in f.read().splitlines() if line.startswith(awalan)]

def konversi_detik(total_detik):
    if total_detik < 0:
        raise ValueError('total_detik tidak boleh negatif')
    jam = total_detik // 3600
    sisa = total_detik % 3600
    menit = sisa // 60
    detik = sisa % 60
    return (jam, menit, detik)

