def koreksi_kuis(kunci, jawaban_siswa):
    rekap = {}
    for nama, jwb in jawaban_siswa.items():
        benar = salah = kosong = 0
        for k, j in zip(kunci, jwb):
            if j == '_':
                kosong += 1
            elif j == k:
                benar += 1
            else:
                salah += 1
        rekap[nama] = {
