practice_labs.solution_code:
def ringkas_transaksi(daftar_baris):
    per_kat = {}
    total = 0
    for baris in daftar_baris:
        bagian = baris.split(':')
        if len(bagian) != 2:
            continue
        kat = bagian[0].strip().lower()
        try:
            nom = int(bagian[1].strip())
        except ValueError:
            continue
        if nom <= 0:
            continue
        per_kat[kat] = per_kat.get(kat, 0) + nom
        total += nom
    return {'per_kategori': per_kat, 'total_semua': total}

def transformasi_sinyal(data):
    hasil = [x * 2 if x >= 0 else 0 for x in data]
    tiga_terbalik = hasil[-3:][::-1]
    return (hasil, tiga_terbalik)

def ratakan_dan_jumlah(data):
    datar = []
    total = 0
    for item in data:
        if isinstance(item, list):
            sub_datar, sub_total = ratakan_dan_jumlah(item)
            datar.extend(sub_datar)
            total += sub_total
        else:
            datar.append(item)
            total += item
    return (datar, total)

def fibonacci_memo(n, memo=None):
    if n < 0:
        raise ValueError('n tidak boleh negatif')
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]

